INSERT INTO `sk2_assemblies` (`id`, `barangay`, `title`, `description`, `schedule_date`, `location`, `status`, `created_at`) VALUES
(1, 'Balug', 'Q1 KK ASSEMBLY', 'I. Opening Program\r\n\r\nPreliminaries (National Anthem, Prayer)\r\n\r\nRoll Call and Determination of Quorum\r\n\r\nII. Approval of the Previous Minutes\r\n\r\nReview and adoption of the last assembly minutes\r\n\r\nIII. SK Chairperson’s Report\r\n\r\nState of the Barangay Youth Address\r\n\r\nFinancial report and accomplishments for the previous quarter\r\n\r\nIV. Proposed Programs and Projects\r\n\r\nPresentation of the proposed programs, projects, and activities (PPAs) for the current year\r\n\r\nDiscussion and approval of the Annual Barangay Youth Investment Program (ABYIP) updates\r\n\r\nV. Open Forum\r\n\r\nIssues, concerns, and suggestions from the youth constituents\r\n\r\nQ&A session regarding youth services and community initiatives\r\n\r\nVI. Announcements\r\n\r\nUpcoming events, registration drives, and community schedules\r\n\r\nVII. Adjournment', '2026-07-14 08:00:00', 'Barangay Hall', 'Upcoming', '2026-07-30 06:22:07'),
(2, 'Balug', 'Q3 KK General Assembly', 'Pagtalakay sa mga bagong programa para sa kabataan, updates sa ABYIP, at open forum para sa mga isyu at suhestiyon ng mga kabataan sa Balug.', '2026-07-31 12:30:00', 'Barangay Balug Covered Court', 'Ongoing', '2026-07-31 04:11:37'),
(3, 'Balug', 'Q4 KK General Assembly', 'Provide a brief summary of what will be discussed (e.g., updates on youth programs, ABYIP budget review, and open forum).', '2026-08-20 08:35:00', 'Barangay Balug Covered Court', 'Upcoming', '2026-08-05 00:36:12'),
(4, 'Balug', 'Special Youth Consultation on Mental Health & Sports', 'Discussion on upcoming barangay sports leagues, mental health awareness programs, and allocation of sports equipment for the youth.', '2026-09-30 08:00:00', 'Barangay Hall Conference Room', 'Upcoming', '2026-08-05 00:36:39');
