INSERT INTO `sk2_dev_plans` (`id`, `barangay`, `plan_type`, `year_coverage`, `center_of_participation`, `objective`, `budget_allocation`, `status`, `created_at`) VALUES
(1, 'Balug', 'ABYIP', '2026', 'Education', 'Isang komprehensibong programa para sa mga kabataan sa barangay upang matuto ng pangunahing web development, digital safety, at computer literacy para sa kanilang kinabukasan.', '25000.00', 'Draft', '2026-07-31 04:12:38'),
(2, 'Balug', 'ABYIP', '2026', 'Health', 'Isang programa na naglalayong magsagawa ng mental health awareness seminar, stress-management workshops, at libreng medical check-up para sa mga kabataan sa barangay upang maitaguyod ang kanilang pisikal at emosyonal na kalusugan.', '15000.00', 'Draft', '2026-08-05 00:23:40'),
(3, 'Balug', 'CBYDP', '2026-2028', 'Active Citizenship', 'Paglulunsad ng taunang inter-purok sports tournament kasabay ng leadership training camp upang mapaunlad ang disiplina, pagkakaisa, at potensyal sa pamumuno ng mga kabataan.', '30000.00', 'Draft', '2026-08-05 00:24:00'),
(4, 'Balug', 'ABYIP', '2026', 'Environment', 'Isang tree-planting at coastal o community clean-up drive kasabay ng environmental awareness workshop upang hikayatin ang mga kabataan na manguna sa pangangalaga ng kalikasan.', '10000.00', 'Draft', '2026-08-05 00:25:31');
