INSERT INTO `sk2_jobs` (`id`, `barangay`, `title`, `type`, `description`, `contact_info`, `status`, `created_at`) VALUES
(1, 'Balug', 'Govt Internship', 'Internship', 'Here are 4 opportunities tailored for the Services Hub:\r\n\r\nJob/Course Title: Barangay SK Youth Development Intern\r\n\r\nType: Govt Internship\r\n\r\nDescription & Requirements: Assist the Sangguniang Kabataan council in organizing community sports leagues, youth profiling, and environmental clean-up drives. Must be 18 to 24 years old, a resident of Barangay Balug, and proficient in basic computer tasks.', '0912-345-6789 / skbalug.internships@gmail.com', 'Open', '2026-08-05 00:30:06'),
(2, 'Balug', 'TESDA Shielded Metal Arc Welding (SMAW NC II)', 'TESDA/Vocational', 'Fully subsidized technical-vocational training program covering basic, common, and core competencies in welding. Open to all Balug residents aged 18 and above who have completed at least Junior High School.', 'TESDA Application Portal', 'Open', '2026-08-05 00:30:25'),
(3, 'Balug', 'Community Barangay Health Worker (BHW) Aide', 'Local Job', 'Support the local health center in immunization drives, medical missions, and updating health records of residents. Must possess good communication skills, be compassionate, and reside within Barangay Balug.', '0998-765-4321 / balughealthunit@yahoo.com', 'Open', '2026-08-05 00:30:40'),
(4, 'Balug', 'TESDA Computer Systems Servicing NC II', 'TESDA/Vocational', 'Hands-on training on installing and configuring computer systems, setting up computer networks, and maintaining hardware/software. Must bring a notebook and have basic computer literacy.', 'Contact Info / Link: Balug Tech-Voc Hub', 'Open', '2026-08-05 00:30:54');
INSERT INTO `sk2_map_locations` (`id`, `barangay`, `name`, `type`, `description`, `created_at`) VALUES
(3, 'Balug', 'Balug Youth Study Nook & Library', 'Study Nook', 'A quiet, well-lit community space equipped with tables, chairs, and basic learning materials for students and out-of-school youth.', '2026-08-05 00:48:39'),
(2, 'Balug', 'Barangay Balug Youth Center & Study Nook', 'Youth Center', 'Isang ligtas at komportableng tambayan at pasilidad para sa mga kabataan sa Barangay Balug kung saan maaari silang mag-aral, mag-meeting, at magsagawa ng mga produktibong aktibidad.', '2026-07-31 04:20:33'),
(6, 'Balug', 'Barangay Balug Covered Court', 'Basketball Court', 'Main multi-purpose outdoor court used for barangay youth leagues, sports tournaments, general assemblies, and community events.', '2026-08-05 00:49:37'),
(5, 'Balug', 'Balug Multipurpose Disaster Safe-Zone', 'Disaster Safe-Zone', 'Primary designated safe zone and emergency shelter equipped for community safety, rescue staging, and relief distribution during calamities.', '2026-08-05 00:49:09');
