INSERT INTO `sk2_safety_resources` (`id`, `barangay`, `title`, `description`, `link`, `created_at`) VALUES
(1, 'Balug', 'Barangay Balug Mental Health & Wellness Guide', 'Gabay para sa mga kabataan sa tamang pangangalaga sa mental health, mga payo laban sa stress at anxiety, at mga tamang hakbang para sa emosyonal na suporta.', 'https://ncmh.gov.ph', '2026-07-31 04:17:56'),
(2, 'Balug', 'Barangay Balug Youth Mental Health & Wellness Guide', 'Gabay para sa mga kabataan sa tamang pangangalaga sa mental health, mga payo laban sa stress at anxiety, at mga tamang hakbang para sa emosyonal na suporta.', 'https://doh.gov.ph/mental-health', '2026-08-05 00:54:28'),
(3, 'Balug', 'Coping with Academic Stress and Burnout', 'Practical strategies for students to manage exam pressure, organize study schedules, and recognize the early signs of burnout.', 'https://who.int/news-room/mental-health', '2026-08-05 00:54:39'),
(4, 'Balug', 'Disaster Preparedness Handbook for Youth', 'Essential safety protocols, typhoon preparedness tips, emergency kit checklists, and immediate response guidelines for flood-prone areas.', 'https://ndrrmc.gov.ph', '2026-08-05 00:54:50');
INSERT INTO `sk2_safe_reports` (`id`, `barangay`, `incident_type`, `description`, `contact_info`, `status`, `created_at`) VALUES
(1, 'Balug', 'Cyberbullying', 'May natanggap na report mula sa isang concerned citizen hinggil sa online harassment at paulit-ulit na panlalait sa social media laban sa isang menor de edad na residente ng Barangay Balug noong Hulyo 30, 2026.', 'Anonymous (Walk-in)', 'Pending Review', '2026-07-31 04:17:26');
INSERT INTO `sk2_scholarships` (`id`, `barangay`, `title`, `description`, `eligibility`, `deadline`, `status`, `created_at`) VALUES
(1, 'Balug', 'SK Balug Educational Assistance Program', 'Isang financial assistance at educational support program para sa mga deserving na college students sa barangay upang makatulong sa kanilang matrikula at school projects ngayong semester.', 'Must be a bonafide resident of Barangay Balug, officially enrolled as an undergraduate college student, and must present a valid school ID and grades.', '2026-08-31', 'Active', '2026-07-31 04:13:11'),
(2, 'Balug', 'SK Balug Senior High School Graduation Support', 'A cash assistance grant intended to help graduating senior high school students with clearance fees, graduation attire, and final school requirements.', 'Must be a resident of Barangay Balug, enrolled in Grade 12, and possess a valid student ID.', '2026-08-25', 'Active', '2026-08-05 00:28:43'),
(3, 'Balug', 'Youth Tech-Voc Scholarship', 'Technical-vocational training subsidy covering tuition and assessment fees for short-term courses (e.g., TESDA-accredited automotive, electrical, or computer systems servicing).', 'Must be 18 to 30 years old, a resident of Barangay Balug, and a high school or senior high school graduate.', '2026-09-15', 'Active', '2026-08-05 00:29:00'),
(4, 'Balug', 'SK Balug Special Needs Educational Aid', 'Financial assistance designed to support students with special education needs, covering specialized learning materials and assistive tools', 'Must be a bonafide resident of Barangay Balug enrolled in any educational level, presenting a valid PWD ID or medical certificate.', '2026-09-30', 'Active', '2026-08-05 00:29:16'),
(5, 'Balug', 'Balug Academic Excellence Grant', 'A merit-based monetary incentive for consistent honor students and dean\'s lister college residents to support their academic books and supplies.', 'Must be a resident of Barangay Balug with a general weighted average of 1.75 or higher (or equivalent honors status) for the previous semester.', '2026-10-10', 'Active', '2026-08-05 00:29:35');
