(1, 'Municipal Level', 'Inter-Barangay Basketball League', 'Annual summer basketball tournament to promote sportsmanship.', 'Promote physical health and keep youth away from vices.', '2026-08-01', '2026-08-30', '150000.00', 'Ongoing', 45, 'https://images.unsplash.com/photo-1546519638-68e109498ffc?auto=format&fit=crop&w=800&q=80', NULL, '2026-07-29 15:14:45', 'medium', NULL),
(2, 'Municipal Level', 'Green Tumauini Tree Planting', 'Planting 1000 mahogany seedlings across riverbanks.', 'Environmental conservation and climate change mitigation.', '2026-09-15', '2026-09-16', '25000.00', 'Planning', 10, 'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&w=800&q=80', NULL, '2026-07-29 15:14:45', 'medium', NULL),
(3, 'Municipal Level', 'Malusog na Kabataan Feeding Program', 'Nutritional feeding for malnourished children in District 1.', 'Eradicate malnutrition among youth aged 5-12.', '2026-07-01', '2026-12-31', '75000.00', 'Ongoing', 60, 'https://images.unsplash.com/photo-1593113565241-db40306c52a0?auto=format&fit=crop&w=800&q=80', NULL, '2026-07-29 15:14:45', 'medium', NULL),
