(6, 'Balug', 'Balug Youth Sports & Leadership Camp 2026', 'A community initiative designed to promote physical wellness, teamwork, and leadership among the youth of Barangay Balug through sports tournaments and youth empowerment workshops.', '1. Foster camaraderie, discipline, and sportsmanship among youth participants.\r\n2. Provide leadership training to develop future community leaders.\r\n3. Promote an active and healthy lifestyle.', '2026-08-01', '2026-08-30', '25000.00', 'Planning', 0, NULL, NULL, '2026-08-01 07:28:35', 'medium', NULL),
(7, 'Santa Visitacion (Maggayu)', 'PROJECT MARENU', 'A project name from the Ybanag word “Marenu” which means “Clean” which aims to emphasize the importance of ecological cleanliness that is not just free from litter, but also reflective of discipline, order, and collective responsibility', '', '2025-01-06', '2025-12-31', '15000.00', 'Ongoing', 50, 'uploads/sk_projects/PROJ_1785820870_4642.png', NULL, '2026-08-04 05:21:10', 'medium', NULL);
